import {Component} from 'react'
import Cookies from 'js-cookie'
import {Redirect} from 'react-router-dom'

import './index.css'

class LoginForm extends Component {
  state = {
    username: '',
    password: '',
    showSubmitError: false,
    errorMsg: '',
    loginForm: true,
  }

  onChangeUsername = event => {
    this.setState({username: event.target.value})
  }

  onChangePassword = event => {
    this.setState({password: event.target.value})
  }

  onSubmitSuccess = jwtToken => {
    const {history} = this.props

    Cookies.set('jwt_token', jwtToken, {
      expires: 30,
      path: '/',
    })
    history.replace('/')
  }

  onSubmitFailure = errorMsg => {
    this.setState({showSubmitError: true, errorMsg})
  }

  submitForm = async event => {
    event.preventDefault()
    const {username, password} = this.state
    const userDetails = {username, password}
    const url = 'https://apis.ccbp.in/login'
    const options = {
      method: 'POST',
      body: JSON.stringify(userDetails),
    }
    const response = await fetch(url, options)
    const data = await response.json()
    if (response.ok === true) {
      this.onSubmitSuccess(data.jwt_token)
    } else {
      this.onSubmitFailure(data.error_msg)
    }
  }

  renderPasswordField = () => {
    const {password} = this.state
    return (
      <>
        <label className="input-label" htmlFor="password">
          PASSWORD
        </label>
        <input
          type="password"
          id="password"
          className="password-input-field"
          value={password}
          onChange={this.onChangePassword}
          placeholder="Password"
        />
      </>
    )
  }

  renderUsernameField = () => {
    const {username} = this.state
    return (
      <>
        <label className="input-label" htmlFor="username">
          USERNAME
        </label>
        <input
          type="text"
          id="username"
          className="username-input-field"
          value={username}
          onChange={this.onChangeUsername}
          placeholder="Username"
        />
      </>
    )
  }

  onClickCreateAccount = async (event) => {
    event.preventDefault()
    this.setState({loginForm:false})
  }

  render() {
    const {showSubmitError, errorMsg,loginForm} = this.state
    const jwtToken = Cookies.get('jwt_token')
    if (jwtToken !== undefined) {
      return <Redirect to="/" />
    }
    return (
      <div>
        <div className="login-form-container">
          <img
            src="https://assets.ccbp.in/frontend/react-js/nxt-trendz-logo-img.png"
            className="login-website-logo-mobile-image"
            alt="website logo"
          />
          <img
            src="https://assets.ccbp.in/frontend/react-js/nxt-trendz-login-img.png"
            className="login-image"
            alt="website login"
          />
          <div>
            <form className="form-container" onSubmit={this.submitForm}>
              <img
                src="https://assets.ccbp.in/frontend/react-js/nxt-trendz-logo-img.png"
                className="login-website-logo-desktop-image"
                alt="website logo"
              />
              {loginForm &&(
                <div>
                  <h1>Login</h1>
                  <div className="input-container">
                    {this.renderUsernameField()}
                  </div>
                  <div className="input-container">
                    {this.renderPasswordField()}
                  </div>
                  <button type="submit" className="login-button">
                    Login
                  </button>
                  {showSubmitError && <p className="error-message">*{errorMsg}</p>}
                  </div>
              )}
              {!loginForm &&(
                <div className='create-account-form'>
                  <h1>Create Account</h1>
                  <>
                    <label>
                      <p>Username</p>
                      <input type='text' placeholder=''/>
                    </label>
                  </>
                </div>
              )}
            </form>
            <form className='account-creation' onSubmit={this.onClickCreateAccount}>
              <button className='create-account' type='submit'><p>Create Account</p></button>
            </form>

            <details className="footer">
              <summary>Click Here for Default Credentials</summary>
              <div className="type-of-user">
                <summary className="prime">
                  <fieldset>
                    <legend>Prime User</legend>
                    <h3>Username : rahul</h3>
                    <h4>Password : rahul@2021</h4>
                  </fieldset>
                </summary>
                <summary className="non-prime">
                  <fieldset>
                    <legend>Non-Prime User</legend>
                    <h3>Username : raja</h3>
                    <h4>Password : raja@2021</h4>
                  </fieldset>
                </summary>
              </div>
            </details>
          </div>
        </div>
      </div>
    )
  }
}

export default LoginForm
